27	package com.google.zxing.oned.rss.expanded.decoders;
28	
29	import com.google.zxing.FormatException;
30	import com.google.zxing.NotFoundException;
31	import com.google.zxing.common.BitArray;
32	
33	/**
34	 * @author Pablo Orduña, University of Deusto (pablo.orduna@deusto.es)
35	 * @author Eduardo Castillejo, University of Deusto (eduardo.castillejo@deusto.es)
36	 */
37	final class GeneralAppIdDecoder {
38	
39	  private final BitArray information;
40	  private final CurrentParsingState current = new CurrentParsingState();
41	  private final StringBuilder buffer = new StringBuilder();
42	
43	  GeneralAppIdDecoder(BitArray information) {
44	    this.information = information;
45	  }
46	
47	  String decodeAllCodes(StringBuilder buff, int initialPosition) throws NotFoundException, FormatException {
48	    int currentPosition = initialPosition;
49	    String remaining = null;
50	    do {
51	      DecodedInformation info = this.decodeGeneralPurposeField(currentPosition, remaining);
52	      String parsedFields = FieldParser.parseFieldsInGeneralPurpose(info.getNewString());
53	      if (parsedFields != null) {
54	        buff.append(parsedFields);
55	      }
56	      if (info.isRemaining()) {
57	        remaining = String.valueOf(info.getRemainingValue());
58	      } else {
59	        remaining = null;
60	      }
61	
62	      if (currentPosition == info.getNewPosition()) { // No step forward!
63	        break;
64	      }
65	      currentPosition = info.getNewPosition();
66	    } while (true);
67	
68	    return buff.toString();
69	  }
70	
71	  private boolean isStillNumeric(int pos) {
72	    // It's numeric if it still has 7 positions
73	    // and one of the first 4 bits is "1".
74	    if (pos + 7 > this.information.getSize()) {
75	      return pos + 4 <= this.information.getSize();
76	    }
77	
78	    for (int i = pos; i < pos + 3; ++i) {
79	      if (this.information.get(i)) {
80	        return true;
81	      }
82	    }
83	
84	    return this.information.get(pos + 3);
85	  }
86	
87	  private DecodedNumeric decodeNumeric(int pos) throws FormatException {
88	    if (pos + 7 > this.information.getSize()) {
89	      int numeric = extractNumericValueFromBitArray(pos, 4);
90	      if (numeric == 0) {
91	        return new DecodedNumeric(this.information.getSize(), DecodedNumeric.FNC1, DecodedNumeric.FNC1);
92	      }
93	      return new DecodedNumeric(this.information.getSize(), numeric - 1, DecodedNumeric.FNC1);
94	    }
95	    int numeric = extractNumericValueFromBitArray(pos, 7);
96	
97	    int digit1  = (numeric - 8) / 11;
98	    int digit2  = (numeric - 8) % 11;
99	
100	    return new DecodedNumeric(pos + 7, digit1, digit2);
101	  }
102	
103	  int extractNumericValueFromBitArray(int pos, int bits) {
104	    return extractNumericValueFromBitArray(this.information, pos, bits);
105	  }
106	
107	  static int extractNumericValueFromBitArray(BitArray information, int pos, int bits) {
108	    int value = 0;
109	    for (int i = 0; i < bits; ++i) {
110	      if (information.get(pos + i)) {
111	        value |= 1 << (bits - i - 1);
112	      }
113	    }
114	
115	    return value;
116	  }
117	
118	  DecodedInformation decodeGeneralPurposeField(int pos, String remaining) throws FormatException {
119	    this.buffer.setLength(0);
120	
121	    if (remaining != null) {
122	      this.buffer.append(remaining);
123	    }
124	
125	    this.current.setPosition(pos);
126	
127	    DecodedInformation lastDecoded = parseBlocks();
128	    if (lastDecoded != null && lastDecoded.isRemaining()) {
129	      return new DecodedInformation(this.current.getPosition(),
130	        this.buffer.toString(), lastDecoded.getRemainingValue());
131	    }
132	    return new DecodedInformation(this.current.getPosition(), this.buffer.toString());
133	  }
134	
135	  private DecodedInformation parseBlocks() throws FormatException {
136	    boolean isFinished;
137	    BlockParsedResult result;
138	    do {
139	      int initialPosition = current.getPosition();
140	
141	      if (current.isAlpha()) {
142	        result = parseAlphaBlock();
143	        isFinished = result.isFinished();
144	      } else if (current.isIsoIec646()) {
145	        result = parseIsoIec646Block();
146	        isFinished = result.isFinished();
147	      } else { // it must be numeric
148	        result = parseNumericBlock();
149	        isFinished = result.isFinished();
150	      }
151	
152	      boolean positionChanged = initialPosition != current.getPosition();
153	      if (!positionChanged && !isFinished) {
154	        break;
155	      }
156	    } while (!isFinished);
157	
158	    return result.getDecodedInformation();
159	  }
160	
161	  private BlockParsedResult parseNumericBlock() throws FormatException {
162	    while (isStillNumeric(current.getPosition())) {
163	      DecodedNumeric numeric = decodeNumeric(current.getPosition());
164	      current.setPosition(numeric.getNewPosition());
165	
166	      if (numeric.isFirstDigitFNC1()) {
167	        DecodedInformation information;
168	        if (numeric.isSecondDigitFNC1()) {
169	          information = new DecodedInformation(current.getPosition(), buffer.toString());
170	        } else {
171	          information = new DecodedInformation(current.getPosition(), buffer.toString(), numeric.getSecondDigit());
172	        }
173	        return new BlockParsedResult(information, true);
174	      }
175	      buffer.append(numeric.getFirstDigit());
176	
177	      if (numeric.isSecondDigitFNC1()) {
178	        DecodedInformation information = new DecodedInformation(current.getPosition(), buffer.toString());
179	        return new BlockParsedResult(information, true);
180	      }
181	      buffer.append(numeric.getSecondDigit());
182	    }
183	
184	    if (isNumericToAlphaNumericLatch(current.getPosition())) {
185	      current.setAlpha();
186	      current.incrementPosition(4);
187	    }
188	    return new BlockParsedResult();
189	  }
190	
191	  private BlockParsedResult parseIsoIec646Block() throws FormatException {
192	    while (isStillIsoIec646(current.getPosition())) {
193	      DecodedChar iso = decodeIsoIec646(current.getPosition());
194	      current.setPosition(iso.getNewPosition());
195	
196	      if (iso.isFNC1()) {
197	        DecodedInformation information = new DecodedInformation(current.getPosition(), buffer.toString());
198	        return new BlockParsedResult(information, true);
199	      }
200	      buffer.append(iso.getValue());
201	    }
202	
203	    if (isAlphaOr646ToNumericLatch(current.getPosition())) {
204	      current.incrementPosition(3);
205	      current.setNumeric();
206	    } else if (isAlphaTo646ToAlphaLatch(current.getPosition())) {
207	      if (current.getPosition() + 5 < this.information.getSize()) {
208	        current.incrementPosition(5);
209	      } else {
210	        current.setPosition(this.information.getSize());
211	      }
212	
213	      current.setAlpha();
214	    }
215	    return new BlockParsedResult();
216	  }
217	
218	  private BlockParsedResult parseAlphaBlock() {
219	    while (isStillAlpha(current.getPosition())) {
220	      DecodedChar alpha = decodeAlphanumeric(current.getPosition());
221	      current.setPosition(alpha.getNewPosition());
222	
223	      if (alpha.isFNC1()) {
224	        DecodedInformation information = new DecodedInformation(current.getPosition(), buffer.toString());
225	        return new BlockParsedResult(information, true); //end of the char block
226	      }
227	
228	      buffer.append(alpha.getValue());
229	    }
230	
231	    if (isAlphaOr646ToNumericLatch(current.getPosition())) {
232	      current.incrementPosition(3);
233	      current.setNumeric();
234	    } else if (isAlphaTo646ToAlphaLatch(current.getPosition())) {
235	      if (current.getPosition() + 5 < this.information.getSize()) {
236	        current.incrementPosition(5);
237	      } else {
238	        current.setPosition(this.information.getSize());
239	      }
240	
241	      current.setIsoIec646();
242	    }
243	    return new BlockParsedResult();
244	  }
245	
246	  private boolean isStillIsoIec646(int pos) {
247	    if (pos + 5 > this.information.getSize()) {
248	      return false;
249	    }
250	
251	    int fiveBitValue = extractNumericValueFromBitArray(pos, 5);
252	    if (fiveBitValue >= 5 && fiveBitValue < 16) {
253	      return true;
254	    }
255	
256	    if (pos + 7 > this.information.getSize()) {
257	      return false;
258	    }
259	
260	    int sevenBitValue = extractNumericValueFromBitArray(pos, 7);
261	    if (sevenBitValue >= 64 && sevenBitValue < 116) {
262	      return true;
263	    }
264	
265	    if (pos + 8 > this.information.getSize()) {
266	      return false;
267	    }
268	
269	    int eightBitValue = extractNumericValueFromBitArray(pos, 8);
270	    return eightBitValue >= 232 && eightBitValue < 253;
271	
272	  }
273	
274	  private DecodedChar decodeIsoIec646(int pos) throws FormatException {
275	    int fiveBitValue = extractNumericValueFromBitArray(pos, 5);
276	    if (fiveBitValue == 15) {
277	      return new DecodedChar(pos + 5, DecodedChar.FNC1);
278	    }
279	
280	    if (fiveBitValue >= 5 && fiveBitValue < 15) {
281	      return new DecodedChar(pos + 5, (char) ('0' + fiveBitValue - 5));
282	    }
283	
284	    int sevenBitValue = extractNumericValueFromBitArray(pos, 7);
285	
286	    if (sevenBitValue >= 64 && sevenBitValue < 90) {
287	      return new DecodedChar(pos + 7, (char) (sevenBitValue + 1));
288	    }
289	
290	    if (sevenBitValue >= 90 && sevenBitValue < 116) {
291	      return new DecodedChar(pos + 7, (char) (sevenBitValue + 7));
292	    }
293	
294	    int eightBitValue = extractNumericValueFromBitArray(pos, 8);
295	    char c;
296	    switch (eightBitValue) {
297	      case 232:
298	        c = '!';
299	        break;
300	      case 233:
301	        c = '"';
302	        break;
303	      case 234:
304	        c = '%';
305	        break;
306	      case 235:
307	        c = '&';
308	        break;
309	      case 236:
310	        c = '\'';
311	        break;
312	      case 237:
313	        c = '(';
314	        break;
315	      case 238:
316	        c = ')';
317	        break;
318	      case 239:
319	        c = '*';
320	        break;
321	      case 240:
322	        c = '+';
323	        break;
324	      case 241:
325	        c = ',';
326	        break;
327	      case 242:
328	        c = '-';
329	        break;
330	      case 243:
331	        c = '.';
332	        break;
333	      case 244:
334	        c = '/';
335	        break;
336	      case 245:
337	        c = ':';
338	        break;
339	      case 246:
340	        c = ';';
341	        break;
342	      case 247:
343	        c = '<';
344	        break;
345	      case 248:
346	        c = '=';
347	        break;
348	      case 249:
349	        c = '>';
350	        break;
351	      case 250:
352	        c = '?';
353	        break;
354	      case 251:
355	        c = '_';
356	        break;
357	      case 252:
358	        c = ' ';
359	        break;
360	      default:
361	        throw FormatException.getFormatInstance();
362	    }
363	    return new DecodedChar(pos + 8, c);
364	  }
365	
366	  private boolean isStillAlpha(int pos) {
367	    if (pos + 5 > this.information.getSize()) {
368	      return false;
369	    }
370	
371	    // We now check if it's a valid 5-bit value (0..9 and FNC1)
372	    int fiveBitValue = extractNumericValueFromBitArray(pos, 5);
373	    if (fiveBitValue >= 5 && fiveBitValue < 16) {
374	      return true;
375	    }
376	
377	    if (pos + 6 > this.information.getSize()) {
378	      return false;
379	    }
380	
381	    int sixBitValue =  extractNumericValueFromBitArray(pos, 6);
382	    return sixBitValue >= 16 && sixBitValue < 63; // 63 not included
383	  }
384	
385	  private DecodedChar decodeAlphanumeric(int pos) {
386	    int fiveBitValue = extractNumericValueFromBitArray(pos, 5);
387	    if (fiveBitValue == 15) {
388	      return new DecodedChar(pos + 5, DecodedChar.FNC1);
389	    }
390	
391	    if (fiveBitValue >= 5 && fiveBitValue < 15) {
392	      return new DecodedChar(pos + 5, (char) ('0' + fiveBitValue - 5));
393	    }
394	
395	    int sixBitValue =  extractNumericValueFromBitArray(pos, 6);
396	
397	    if (sixBitValue >= 32 && sixBitValue < 58) {
398	      return new DecodedChar(pos + 6, (char) (sixBitValue + 33));
399	    }
400	
401	    char c;
402	    switch (sixBitValue) {
403	      case 58:
404	        c = '*';
405	        break;
406	      case 59:
407	        c = ',';
408	        break;
409	      case 60:
410	        c = '-';
411	        break;
412	      case 61:
413	        c = '.';
414	        break;
415	      case 62:
416	        c = '/';
417	        break;
418	      default:
419	        throw new IllegalStateException("Decoding invalid alphanumeric value: " + sixBitValue);
420	    }
421	    return new DecodedChar(pos + 6, c);
422	  }
423	
424	  private boolean isAlphaTo646ToAlphaLatch(int pos) {
425	    if (pos + 1 > this.information.getSize()) {
426	      return false;
427	    }
428	
429	    for (int i = 0; i < 5 && i + pos < this.information.getSize(); ++i) {
430	      if (i == 2) {
431	        if (!this.information.get(pos + 2)) {
432	          return false;
433	        }
434	      } else if (this.information.get(pos + i)) {
435	        return false;
436	      }
437	    }
438	
439	    return true;
440	  }
441	
442	  private boolean isAlphaOr646ToNumericLatch(int pos) {
443	    // Next is alphanumeric if there are 3 positions and they are all zeros
444	    if (pos + 3 > this.information.getSize()) {
445	      return false;
446	    }
447	
448	    for (int i = pos; i < pos + 3; ++i) {
449	      if (this.information.get(i)) {
450	        return false;
451	      }
452	    }
453	    return true;
454	  }
455	
456	  private boolean isNumericToAlphaNumericLatch(int pos) {
457	    // Next is alphanumeric if there are 4 positions and they are all zeros, or
458	    // if there is a subset of this just before the end of the symbol
459	    if (pos + 1 > this.information.getSize()) {
460	      return false;
461	    }
462	
463	    for (int i = 0; i < 4 && i + pos < this.information.getSize(); ++i) {
464	      if (this.information.get(pos + i)) {
465	        return false;
466	      }
467	    }
468	    return true;
469	  }
470	}
