17	package com.google.zxing.multi.qrcode;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.BinaryBitmap;
21	import com.google.zxing.DecodeHintType;
22	import com.google.zxing.NotFoundException;
23	import com.google.zxing.ReaderException;
24	import com.google.zxing.Result;
25	import com.google.zxing.ResultMetadataType;
26	import com.google.zxing.ResultPoint;
27	import com.google.zxing.common.DecoderResult;
28	import com.google.zxing.common.DetectorResult;
29	import com.google.zxing.multi.MultipleBarcodeReader;
30	import com.google.zxing.multi.qrcode.detector.MultiDetector;
31	import com.google.zxing.qrcode.QRCodeReader;
32	import com.google.zxing.qrcode.decoder.QRCodeDecoderMetaData;
33	
34	import java.io.ByteArrayOutputStream;
35	import java.io.Serializable;
36	import java.util.ArrayList;
37	import java.util.List;
38	import java.util.Map;
39	import java.util.Collections;
40	import java.util.Comparator;
41	
42	/**
43	 * This implementation can detect and decode multiple QR Codes in an image.
44	 *
45	 * @author Sean Owen
46	 * @author Hannes Erven
47	 */
48	public final class QRCodeMultiReader extends QRCodeReader implements MultipleBarcodeReader {
49	
50	  private static final Result[] EMPTY_RESULT_ARRAY = new Result[0];
51	  private static final ResultPoint[] NO_POINTS = new ResultPoint[0];
52	
53	  @Override
54	  public Result[] decodeMultiple(BinaryBitmap image) throws NotFoundException {
55	    return decodeMultiple(image, null);
56	  }
57	
58	  @Override
59	  public Result[] decodeMultiple(BinaryBitmap image, Map<DecodeHintType,?> hints) throws NotFoundException {
60	    List<Result> results = new ArrayList<>();
61	    DetectorResult[] detectorResults = new MultiDetector(image.getBlackMatrix()).detectMulti(hints);
62	    for (DetectorResult detectorResult : detectorResults) {
63	      try {
64	        DecoderResult decoderResult = getDecoder().decode(detectorResult.getBits(), hints);
65	        ResultPoint[] points = detectorResult.getPoints();
66	        // If the code was mirrored: swap the bottom-left and the top-right points.
67	        if (decoderResult.getOther() instanceof QRCodeDecoderMetaData) {
68	          ((QRCodeDecoderMetaData) decoderResult.getOther()).applyMirroredCorrection(points);
69	        }
70	        Result result = new Result(decoderResult.getText(), decoderResult.getRawBytes(), points,
71	                                   BarcodeFormat.QR_CODE);
72	        List<byte[]> byteSegments = decoderResult.getByteSegments();
73	        if (byteSegments != null) {
74	          result.putMetadata(ResultMetadataType.BYTE_SEGMENTS, byteSegments);
75	        }
76	        String ecLevel = decoderResult.getECLevel();
77	        if (ecLevel != null) {
78	          result.putMetadata(ResultMetadataType.ERROR_CORRECTION_LEVEL, ecLevel);
79	        }
80	        if (decoderResult.hasStructuredAppend()) {
81	          result.putMetadata(ResultMetadataType.STRUCTURED_APPEND_SEQUENCE,
82	                             decoderResult.getStructuredAppendSequenceNumber());
83	          result.putMetadata(ResultMetadataType.STRUCTURED_APPEND_PARITY,
84	                             decoderResult.getStructuredAppendParity());
85	        }
86	        result.putMetadata(ResultMetadataType.ERRORS_CORRECTED, decoderResult.getErrorsCorrected());
87	        // Fix SYMBOLOGY_IDENTIFIER loss in QRCodeMultiReader
88	        result.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]Q" + decoderResult.getSymbologyModifier());
89	
90	        results.add(result);
91	      } catch (ReaderException re) {
92	        // ignore and continue
93	      }
94	    }
95	    if (results.isEmpty()) {
96	      return EMPTY_RESULT_ARRAY;
97	    } else {
98	      results = processStructuredAppend(results);
99	      return results.toArray(EMPTY_RESULT_ARRAY);
100	    }
101	  }
102	
103	  static List<Result> processStructuredAppend(List<Result> results) {
104	    List<Result> newResults = new ArrayList<>();
105	    List<Result> saResults = new ArrayList<>();
106	    for (Result result : results) {
107	      if (result.getResultMetadata().containsKey(ResultMetadataType.STRUCTURED_APPEND_SEQUENCE)) {
108	        saResults.add(result);
109	      } else {
110	        newResults.add(result);
111	      }
112	    }
113	    if (saResults.isEmpty()) {
114	      return results;
115	    }
116	
117	    // sort and concatenate the SA list items
118	    Collections.sort(saResults, new SAComparator());
119	    StringBuilder newText = new StringBuilder();
120	    ByteArrayOutputStream newRawBytes = new ByteArrayOutputStream();
121	    ByteArrayOutputStream newByteSegment = new ByteArrayOutputStream();
122	    for (Result saResult : saResults) {
123	      newText.append(saResult.getText());
124	      byte[] saBytes = saResult.getRawBytes();
125	      newRawBytes.write(saBytes, 0, saBytes.length);
126	      @SuppressWarnings("unchecked")
127	      Iterable<byte[]> byteSegments =
128	          (Iterable<byte[]>) saResult.getResultMetadata().get(ResultMetadataType.BYTE_SEGMENTS);
129	      if (byteSegments != null) {
130	        for (byte[] segment : byteSegments) {
131	          newByteSegment.write(segment, 0, segment.length);
132	        }
133	      }
134	    }
135	
136	    Result newResult = new Result(newText.toString(), newRawBytes.toByteArray(), NO_POINTS, BarcodeFormat.QR_CODE);
137	    if (newByteSegment.size() > 0) {
138	      newResult.putMetadata(ResultMetadataType.BYTE_SEGMENTS, Collections.singletonList(newByteSegment.toByteArray()));
139	    }
140	    newResults.add(newResult);
141	    return newResults;
142	  }
143	
144	  private static final class SAComparator implements Comparator<Result>, Serializable {
145	    @Override
146	    public int compare(Result a, Result b) {
147	      int aNumber = (int) a.getResultMetadata().get(ResultMetadataType.STRUCTURED_APPEND_SEQUENCE);
148	      int bNumber = (int) b.getResultMetadata().get(ResultMetadataType.STRUCTURED_APPEND_SEQUENCE);
149	      return Integer.compare(aNumber, bNumber);
150	    }
151	  }
152	
153	}
