35	/**
36	 * <p>This class attempts to find finder patterns in a QR Code. Finder patterns are the square
37	 * markers at three corners of a QR Code.</p>
38	 *
39	 * <p>This class is thread-safe but not reentrant. Each thread must allocate its own object.
40	 *
41	 * <p>In contrast to {@link FinderPatternFinder}, this class will return an array of all possible
42	 * QR code locations in the image.</p>
43	 *
44	 * <p>Use the TRY_HARDER hint to ask for a more thorough detection.</p>
45	 *
46	 * @author Sean Owen
47	 * @author Hannes Erven
48	 */
49	public final class MultiFinderPatternFinder extends FinderPatternFinder {
50	
51	  private static final FinderPatternInfo[] EMPTY_RESULT_ARRAY = new FinderPatternInfo[0];
52	  private static final FinderPattern[] EMPTY_FP_ARRAY = new FinderPattern[0];
53	  private static final FinderPattern[][] EMPTY_FP_2D_ARRAY = new FinderPattern[0][];
54	
55	  // TODO MIN_MODULE_COUNT and MAX_MODULE_COUNT would be great hints to ask the user for
56	  // since it limits the number of regions to decode
57	
58	  // max. legal count of modules per QR code edge (177)
59	  private static final float MAX_MODULE_COUNT_PER_EDGE = 180;
60	  // min. legal count per modules per QR code edge (11)
61	  private static final float MIN_MODULE_COUNT_PER_EDGE = 9;
62	
63	  /**
64	   * More or less arbitrary cutoff point for determining if two finder patterns might belong
65	   * to the same code if they differ less than DIFF_MODSIZE_CUTOFF_PERCENT percent in their
66	   * estimated modules sizes.
67	   */
68	  private static final float DIFF_MODSIZE_CUTOFF_PERCENT = 0.05f;
69	
70	  /**
71	   * More or less arbitrary cutoff point for determining if two finder patterns might belong
72	   * to the same code if they differ less than DIFF_MODSIZE_CUTOFF pixels/module in their
73	   * estimated modules sizes.
74	   */
75	  private static final float DIFF_MODSIZE_CUTOFF = 0.5f;
76	
77	
78	  /**
79	   * A comparator that orders FinderPatterns by their estimated module size.
80	   */
81	  private static final class ModuleSizeComparator implements Comparator<FinderPattern>, Serializable {
82	    @Override
83	    public int compare(FinderPattern center1, FinderPattern center2) {
84	      float value = center2.getEstimatedModuleSize() - center1.getEstimatedModuleSize();
85	      return value < 0.0 ? -1 : value > 0.0 ? 1 : 0;
86	    }
87	  }
88	
89	  public MultiFinderPatternFinder(BitMatrix image, ResultPointCallback resultPointCallback) {
90	    super(image, resultPointCallback);
91	  }
92	
93	  /**
94	   * @return the 3 best {@link FinderPattern}s from our list of candidates. The "best" are
95	   *         those that have been detected at least 2 times, and whose module
96	   *         size differs from the average among those patterns the least
97	   * @throws NotFoundException if 3 such finder patterns do not exist
98	   */
99	  private FinderPattern[][] selectMultipleBestPatterns() throws NotFoundException {
100	    List<FinderPattern> possibleCenters = new ArrayList<>();
101	    for (FinderPattern fp : getPossibleCenters()) {
102	      if (fp.getCount() >= 2) {
103	        possibleCenters.add(fp);
104	      }
105	    }
106	    int size = possibleCenters.size();
107	
108	    if (size < 3) {
109	      // Couldn't find enough finder patterns
110	      throw NotFoundException.getNotFoundInstance();
111	    }
112	
113	    /*
114	     * Begin HE modifications to safely detect multiple codes of equal size
115	     */
116	    if (size == 3) {
117	      return new FinderPattern[][] { possibleCenters.toArray(EMPTY_FP_ARRAY) };
118	    }
119	
120	    // Sort by estimated module size to speed up the upcoming checks
121	    Collections.sort(possibleCenters, new ModuleSizeComparator());
122	
123	    /*
124	     * Now lets start: build a list of tuples of three finder locations that
125	     *  - feature similar module sizes
126	     *  - are placed in a distance so the estimated module count is within the QR specification
127	     *  - have similar distance between upper left/right and left top/bottom finder patterns
128	     *  - form a triangle with 90° angle (checked by comparing top right/bottom left distance
129	     *    with pythagoras)
130	     *
131	     * Note: we allow each point to be used for more than one code region: this might seem
132	     * counterintuitive at first, but the performance penalty is not that big. At this point,
133	     * we cannot make a good quality decision whether the three finders actually represent
134	     * a QR code, or are just by chance laid out so it looks like there might be a QR code there.
135	     * So, if the layout seems right, lets have the decoder try to decode.
136	     */
137	
138	    List<FinderPattern[]> results = new ArrayList<>(); // holder for the results
139	
140	    for (int i1 = 0; i1 < (size - 2); i1++) {
141	      FinderPattern p1 = possibleCenters.get(i1);
142	      if (p1 == null) {
143	        continue;
144	      }
145	
146	      for (int i2 = i1 + 1; i2 < (size - 1); i2++) {
147	        FinderPattern p2 = possibleCenters.get(i2);
148	        if (p2 == null) {
149	          continue;
150	        }
151	
152	        // Compare the expected module sizes; if they are really off, skip
153	        float vModSize12 = (p1.getEstimatedModuleSize() - p2.getEstimatedModuleSize()) /
154	            Math.min(p1.getEstimatedModuleSize(), p2.getEstimatedModuleSize());
155	        float vModSize12A = Math.abs(p1.getEstimatedModuleSize() - p2.getEstimatedModuleSize());
156	        if (vModSize12A > DIFF_MODSIZE_CUTOFF && vModSize12 >= DIFF_MODSIZE_CUTOFF_PERCENT) {
157	          // break, since elements are ordered by the module size deviation there cannot be
158	          // any more interesting elements for the given p1.
159	          break;
160	        }
161	
162	        for (int i3 = i2 + 1; i3 < size; i3++) {
163	          FinderPattern p3 = possibleCenters.get(i3);
164	          if (p3 == null) {
165	            continue;
166	          }
167	
168	          // Compare the expected module sizes; if they are really off, skip
169	          float vModSize23 = (p2.getEstimatedModuleSize() - p3.getEstimatedModuleSize()) /
170	              Math.min(p2.getEstimatedModuleSize(), p3.getEstimatedModuleSize());
171	          float vModSize23A = Math.abs(p2.getEstimatedModuleSize() - p3.getEstimatedModuleSize());
172	          if (vModSize23A > DIFF_MODSIZE_CUTOFF && vModSize23 >= DIFF_MODSIZE_CUTOFF_PERCENT) {
173	            // break, since elements are ordered by the module size deviation there cannot be
174	            // any more interesting elements for the given p1.
175	            break;
176	          }
177	
178	          FinderPattern[] test = {p1, p2, p3};
179	          ResultPoint.orderBestPatterns(test);
180	
181	          // Calculate the distances: a = topleft-bottomleft, b=topleft-topright, c = diagonal
182	          FinderPatternInfo info = new FinderPatternInfo(test);
183	          float dA = ResultPoint.distance(info.getTopLeft(), info.getBottomLeft());
184	          float dC = ResultPoint.distance(info.getTopRight(), info.getBottomLeft());
185	          float dB = ResultPoint.distance(info.getTopLeft(), info.getTopRight());
186	
187	          // Check the sizes
188	          float estimatedModuleCount = (dA + dB) / (p1.getEstimatedModuleSize() * 2.0f);
189	          if (estimatedModuleCount > MAX_MODULE_COUNT_PER_EDGE ||
190	              estimatedModuleCount < MIN_MODULE_COUNT_PER_EDGE) {
191	            continue;
192	          }
193	
194	          // Calculate the difference of the edge lengths in percent
195	          float vABBC = Math.abs((dA - dB) / Math.min(dA, dB));
196	          if (vABBC >= 0.1f) {
197	            continue;
198	          }
199	
200	          // Calculate the diagonal length by assuming a 90° angle at topleft
201	          float dCpy = (float) Math.sqrt((double) dA * dA + (double) dB * dB);
202	          // Compare to the real distance in %
203	          float vPyC = Math.abs((dC - dCpy) / Math.min(dC, dCpy));
204	
205	          if (vPyC >= 0.1f) {
206	            continue;
207	          }
208	
209	          // All tests passed!
210	          results.add(test);
211	        }
212	      }
213	    }
214	
215	    if (!results.isEmpty()) {
216	      return results.toArray(EMPTY_FP_2D_ARRAY);
217	    }
218	
219	    // Nothing found!
220	    throw NotFoundException.getNotFoundInstance();
221	  }
222	
223	  public FinderPatternInfo[] findMulti(Map<DecodeHintType,?> hints) throws NotFoundException {
224	    boolean tryHarder = hints != null && hints.containsKey(DecodeHintType.TRY_HARDER);
225	    BitMatrix image = getImage();
226	    int maxI = image.getHeight();
227	    int maxJ = image.getWidth();
228	    // We are looking for black/white/black/white/black modules in
229	    // 1:1:3:1:1 ratio; this tracks the number of such modules seen so far
230	
231	    // Let's assume that the maximum version QR Code we support takes up 1/4 the height of the
232	    // image, and then account for the center being 3 modules in size. This gives the smallest
233	    // number of pixels the center could be, so skip this often. When trying harder, look for all
234	    // QR versions regardless of how dense they are.
235	    int iSkip = (3 * maxI) / (4 * MAX_MODULES);
236	    if (iSkip < MIN_SKIP || tryHarder) {
237	      iSkip = MIN_SKIP;
238	    }
239	
240	    int[] stateCount = new int[5];
241	    for (int i = iSkip - 1; i < maxI; i += iSkip) {
242	      // Get a row of black/white values
243	      doClearCounts(stateCount);
244	      int currentState = 0;
245	      for (int j = 0; j < maxJ; j++) {
246	        if (image.get(j, i)) {
247	          // Black pixel
248	          if ((currentState & 1) == 1) { // Counting white pixels
249	            currentState++;
250	          }
251	          stateCount[currentState]++;
252	        } else { // White pixel
253	          if ((currentState & 1) == 0) { // Counting black pixels
254	            if (currentState == 4) { // A winner?
255	              if (foundPatternCross(stateCount) && handlePossibleCenter(stateCount, i, j)) { // Yes
256	                // Clear state to start looking again
257	                currentState = 0;
258	                doClearCounts(stateCount);
259	              } else { // No, shift counts back by two
260	                doShiftCounts2(stateCount);
261	                currentState = 3;
262	              }
263	            } else {
264	              stateCount[++currentState]++;
265	            }
266	          } else { // Counting white pixels
267	            stateCount[currentState]++;
268	          }
269	        }
270	      } // for j=...
271	
272	      if (foundPatternCross(stateCount)) {
273	        handlePossibleCenter(stateCount, i, maxJ);
274	      }
275	    } // for i=iSkip-1 ...
276	    FinderPattern[][] patternInfo = selectMultipleBestPatterns();
277	    List<FinderPatternInfo> result = new ArrayList<>();
278	    for (FinderPattern[] pattern : patternInfo) {
279	      ResultPoint.orderBestPatterns(pattern);
280	      result.add(new FinderPatternInfo(pattern));
281	    }
282	
283	    if (result.isEmpty()) {
284	      return EMPTY_RESULT_ARRAY;
285	    } else {
286	      return result.toArray(EMPTY_RESULT_ARRAY);
287	    }
288	  }
289	
