17	package com.google.zxing.oned;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.DecodeHintType;
21	import com.google.zxing.NotFoundException;
22	import com.google.zxing.Result;
23	import com.google.zxing.ResultMetadataType;
24	import com.google.zxing.ResultPoint;
25	import com.google.zxing.common.BitArray;
26	
27	import java.util.Arrays;
28	import java.util.Map;
29	
30	/**
31	 * <p>Decodes Codabar barcodes.</p>
32	 *
33	 * @author Bas Vijfwinkel
34	 * @author David Walker
35	 */
36	public final class CodaBarReader extends OneDReader {
37	
38	  // These values are critical for determining how permissive the decoding
39	  // will be. All stripe sizes must be within the window these define, as
40	  // compared to the average stripe size.
41	  private static final float MAX_ACCEPTABLE = 2.0f;
42	  private static final float PADDING = 1.5f;
43	
44	  private static final String ALPHABET_STRING = "0123456789-$:/.+ABCD";
45	  static final char[] ALPHABET = ALPHABET_STRING.toCharArray();
46	
47	  /**
48	   * These represent the encodings of characters, as patterns of wide and narrow bars. The 7 least-significant bits of
49	   * each int correspond to the pattern of wide and narrow, with 1s representing "wide" and 0s representing narrow.
50	   */
51	  static final int[] CHARACTER_ENCODINGS = {
52	      0x003, 0x006, 0x009, 0x060, 0x012, 0x042, 0x021, 0x024, 0x030, 0x048, // 0-9
53	      0x00c, 0x018, 0x045, 0x051, 0x054, 0x015, 0x01A, 0x029, 0x00B, 0x00E, // -$:/.+ABCD
54	  };
55	
56	  // minimal number of characters that should be present (including start and stop characters)
57	  // under normal circumstances this should be set to 3, but can be set higher
58	  // as a last-ditch attempt to reduce false positives.
59	  private static final int MIN_CHARACTER_LENGTH = 3;
60	
61	  // official start and end patterns
62	  private static final char[] STARTEND_ENCODING = {'A', 'B', 'C', 'D'};
63	  // some Codabar generator allow the Codabar string to be closed by every
64	  // character. This will cause lots of false positives!
65	
66	  // some industries use a checksum standard but this is not part of the original Codabar standard
67	  // for more information see : http://www.mecsw.com/specs/codabar.html
68	
69	  // Keep some instance variables to avoid reallocations
70	  private final StringBuilder decodeRowResult;
71	  private int[] counters;
72	  private int counterLength;
73	
74	  public CodaBarReader() {
75	    decodeRowResult = new StringBuilder(20);
76	    counters = new int[80];
77	    counterLength = 0;
78	  }
79	
80	  @Override
81	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints) throws NotFoundException {
82	
83	    Arrays.fill(counters, 0);
84	    setCounters(row);
85	    int startOffset = findStartPattern();
86	    int nextStart = startOffset;
87	
88	    decodeRowResult.setLength(0);
89	    do {
90	      int charOffset = toNarrowWidePattern(nextStart);
91	      if (charOffset == -1) {
92	        throw NotFoundException.getNotFoundInstance();
93	      }
94	      // Hack: We store the position in the alphabet table into a
95	      // StringBuilder, so that we can access the decoded patterns in
96	      // validatePattern. We'll translate to the actual characters later.
97	      decodeRowResult.append((char) charOffset);
98	      nextStart += 8;
99	      // Stop as soon as we see the end character.
100	      if (decodeRowResult.length() > 1 &&
101	          arrayContains(STARTEND_ENCODING, ALPHABET[charOffset])) {
102	        break;
103	      }
104	    } while (nextStart < counterLength); // no fixed end pattern so keep on reading while data is available
105	
106	    // Look for whitespace after pattern:
107	    int trailingWhitespace = counters[nextStart - 1];
108	    int lastPatternSize = 0;
109	    for (int i = -8; i < -1; i++) {
110	      lastPatternSize += counters[nextStart + i];
111	    }
112	
113	    // We need to see whitespace equal to 50% of the last pattern size,
114	    // otherwise this is probably a false positive. The exception is if we are
115	    // at the end of the row. (I.e. the barcode barely fits.)
116	    if (nextStart < counterLength && trailingWhitespace < lastPatternSize / 2) {
117	      throw NotFoundException.getNotFoundInstance();
118	    }
119	
120	    validatePattern(startOffset);
121	
122	    // Translate character table offsets to actual characters.
123	    for (int i = 0; i < decodeRowResult.length(); i++) {
124	      decodeRowResult.setCharAt(i, ALPHABET[decodeRowResult.charAt(i)]);
125	    }
126	    // Ensure a valid start and end character
127	    char startchar = decodeRowResult.charAt(0);
128	    if (!arrayContains(STARTEND_ENCODING, startchar)) {
129	      throw NotFoundException.getNotFoundInstance();
130	    }
131	    char endchar = decodeRowResult.charAt(decodeRowResult.length() - 1);
132	    if (!arrayContains(STARTEND_ENCODING, endchar)) {
133	      throw NotFoundException.getNotFoundInstance();
134	    }
135	
136	    // remove stop/start characters character and check if a long enough string is contained
137	    if (decodeRowResult.length() <= MIN_CHARACTER_LENGTH) {
138	      // Almost surely a false positive ( start + stop + at least 1 character)
139	      throw NotFoundException.getNotFoundInstance();
140	    }
141	
142	    if (hints == null || !hints.containsKey(DecodeHintType.RETURN_CODABAR_START_END)) {
143	      decodeRowResult.deleteCharAt(decodeRowResult.length() - 1);
144	      decodeRowResult.deleteCharAt(0);
145	    }
146	
147	    int runningCount = 0;
148	    for (int i = 0; i < startOffset; i++) {
149	      runningCount += counters[i];
150	    }
151	    float left = runningCount;
152	    for (int i = startOffset; i < nextStart - 1; i++) {
153	      runningCount += counters[i];
154	    }
155	    float right = runningCount;
156	
157	    Result result = new Result(
158	        decodeRowResult.toString(),
159	        null,
160	        new ResultPoint[]{
161	            new ResultPoint(left, rowNumber),
162	            new ResultPoint(right, rowNumber)},
163	        BarcodeFormat.CODABAR);
164	    result.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]F0");
165	    return result;
166	  }
167	
168	  private void validatePattern(int start) throws NotFoundException {
169	    // First, sum up the total size of our four categories of stripe sizes;
170	    int[] sizes = {0, 0, 0, 0};
171	    int[] counts = {0, 0, 0, 0};
172	    int end = decodeRowResult.length() - 1;
173	
174	    // We break out of this loop in the middle, in order to handle
175	    // inter-character spaces properly.
176	    int pos = start;
177	    for (int i = 0; i <= end; i++) {
178	      int pattern = CHARACTER_ENCODINGS[decodeRowResult.charAt(i)];
179	      for (int j = 6; j >= 0; j--) {
180	        // Even j = bars, while odd j = spaces. Categories 2 and 3 are for
181	        // long stripes, while 0 and 1 are for short stripes.
182	        int category = (j & 1) + (pattern & 1) * 2;
183	        sizes[category] += counters[pos + j];
184	        counts[category]++;
185	        pattern >>= 1;
186	      }
187	      // We ignore the inter-character space - it could be of any size.
188	      pos += 8;
189	    }
190	
191	    // Calculate our allowable size thresholds using fixed-point math.
192	    float[] maxes = new float[4];
193	    float[] mins = new float[4];
194	    // Define the threshold of acceptability to be the midpoint between the
195	    // average small stripe and the average large stripe. No stripe lengths
196	    // should be on the "wrong" side of that line.
197	    for (int i = 0; i < 2; i++) {
198	      mins[i] = 0.0f;  // Accept arbitrarily small "short" stripes.
199	      mins[i + 2] = ((float) sizes[i] / counts[i] + (float) sizes[i + 2] / counts[i + 2]) / 2.0f;
200	      maxes[i] = mins[i + 2];
201	      maxes[i + 2] = (sizes[i + 2] * MAX_ACCEPTABLE + PADDING) / counts[i + 2];
202	    }
203	
204	    // Now verify that all of the stripes are within the thresholds.
205	    pos = start;
206	    for (int i = 0; i <= end; i++) {
207	      int pattern = CHARACTER_ENCODINGS[decodeRowResult.charAt(i)];
208	      for (int j = 6; j >= 0; j--) {
209	        // Even j = bars, while odd j = spaces. Categories 2 and 3 are for
210	        // long stripes, while 0 and 1 are for short stripes.
211	        int category = (j & 1) + (pattern & 1) * 2;
212	        int size = counters[pos + j];
213	        if (size < mins[category] || size > maxes[category]) {
214	          throw NotFoundException.getNotFoundInstance();
215	        }
216	        pattern >>= 1;
217	      }
218	      pos += 8;
219	    }
220	  }
221	
222	  /**
223	   * Records the size of all runs of white and black pixels, starting with white.
224	   * This is just like recordPattern, except it records all the counters, and
225	   * uses our builtin "counters" member for storage.
226	   * @param row row to count from
227	   */
228	  private void setCounters(BitArray row) throws NotFoundException {
229	    counterLength = 0;
230	    // Start from the first white bit.
231	    int i = row.getNextUnset(0);
232	    int end = row.getSize();
233	    if (i >= end) {
234	      throw NotFoundException.getNotFoundInstance();
235	    }
236	    boolean isWhite = true;
237	    int count = 0;
238	    while (i < end) {
239	      if (row.get(i) != isWhite) {
240	        count++;
241	      } else {
242	        counterAppend(count);
243	        count = 1;
244	        isWhite = !isWhite;
245	      }
246	      i++;
247	    }
248	    counterAppend(count);
249	  }
250	
251	  private void counterAppend(int e) {
252	    counters[counterLength] = e;
253	    counterLength++;
254	    if (counterLength >= counters.length) {
255	      int[] temp = new int[counterLength * 2];
256	      System.arraycopy(counters, 0, temp, 0, counterLength);
257	      counters = temp;
258	    }
259	  }
260	
261	  private int findStartPattern() throws NotFoundException {
262	    for (int i = 1; i < counterLength; i += 2) {
263	      int charOffset = toNarrowWidePattern(i);
264	      if (charOffset != -1 && arrayContains(STARTEND_ENCODING, ALPHABET[charOffset])) {
265	        // Look for whitespace before start pattern, >= 50% of width of start pattern
266	        // We make an exception if the whitespace is the first element.
267	        int patternSize = 0;
268	        for (int j = i; j < i + 7; j++) {
269	          patternSize += counters[j];
270	        }
271	        if (i == 1 || counters[i - 1] >= patternSize / 2) {
272	          return i;
273	        }
274	      }
275	    }
276	    throw NotFoundException.getNotFoundInstance();
277	  }
278	
279	  static boolean arrayContains(char[] array, char key) {
280	    if (array != null) {
281	      for (char c : array) {
282	        if (c == key) {
283	          return true;
284	        }
285	      }
286	    }
287	    return false;
288	  }
289	
290	  // Assumes that counters[position] is a bar.
291	  private int toNarrowWidePattern(int position) {
292	    int end = position + 7;
293	    if (end >= counterLength) {
294	      return -1;
295	    }
296	
297	    int[] theCounters = counters;
298	
299	    int maxBar = 0;
300	    int minBar = Integer.MAX_VALUE;
301	    for (int j = position; j < end; j += 2) {
302	      int currentCounter = theCounters[j];
303	      if (currentCounter < minBar) {
304	        minBar = currentCounter;
305	      }
306	      if (currentCounter > maxBar) {
307	        maxBar = currentCounter;
308	      }
309	    }
310	    int thresholdBar = (minBar + maxBar) / 2;
311	
312	    int maxSpace = 0;
313	    int minSpace = Integer.MAX_VALUE;
314	    for (int j = position + 1; j < end; j += 2) {
315	      int currentCounter = theCounters[j];
316	      if (currentCounter < minSpace) {
317	        minSpace = currentCounter;
318	      }
319	      if (currentCounter > maxSpace) {
320	        maxSpace = currentCounter;
321	      }
322	    }
323	    int thresholdSpace = (minSpace + maxSpace) / 2;
324	
325	    int bitmask = 1 << 7;
326	    int pattern = 0;
327	    for (int i = 0; i < 7; i++) {
328	      int threshold = (i & 1) == 0 ? thresholdBar : thresholdSpace;
329	      bitmask >>= 1;
330	      if (theCounters[position + i] > threshold) {
331	        pattern |= bitmask;
332	      }
333	    }
334	
335	    for (int i = 0; i < CHARACTER_ENCODINGS.length; i++) {
336	      if (CHARACTER_ENCODINGS[i] == pattern) {
337	        return i;
338	      }
339	    }
340	    return -1;
341	  }
342	
343	}
