17	package com.google.zxing.oned;
18	
19	import com.google.zxing.BarcodeFormat;
20	import com.google.zxing.ChecksumException;
21	import com.google.zxing.DecodeHintType;
22	import com.google.zxing.FormatException;
23	import com.google.zxing.NotFoundException;
24	import com.google.zxing.Result;
25	import com.google.zxing.ResultMetadataType;
26	import com.google.zxing.ResultPoint;
27	import com.google.zxing.common.BitArray;
28	import com.google.zxing.common.detector.MathUtils;
29	
30	import java.util.Arrays;
31	import java.util.Map;
32	
33	/**
34	 * <p>Decodes Code 93 barcodes.</p>
35	 *
36	 * @author Sean Owen
37	 * @see Code39Reader
38	 */
39	public final class Code93Reader extends OneDReader {
40	
41	  // Note that 'abcd' are dummy characters in place of control characters.
42	  static final String ALPHABET_STRING = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%abcd*";
43	  private static final char[] ALPHABET = ALPHABET_STRING.toCharArray();
44	
45	  /**
46	   * These represent the encodings of characters, as patterns of wide and narrow bars.
47	   * The 9 least-significant bits of each int correspond to the pattern of wide and narrow.
48	   */
49	  static final int[] CHARACTER_ENCODINGS = {
50	      0x114, 0x148, 0x144, 0x142, 0x128, 0x124, 0x122, 0x150, 0x112, 0x10A, // 0-9
51	      0x1A8, 0x1A4, 0x1A2, 0x194, 0x192, 0x18A, 0x168, 0x164, 0x162, 0x134, // A-J
52	      0x11A, 0x158, 0x14C, 0x146, 0x12C, 0x116, 0x1B4, 0x1B2, 0x1AC, 0x1A6, // K-T
53	      0x196, 0x19A, 0x16C, 0x166, 0x136, 0x13A, // U-Z
54	      0x12E, 0x1D4, 0x1D2, 0x1CA, 0x16E, 0x176, 0x1AE, // - - %
55	      0x126, 0x1DA, 0x1D6, 0x132, 0x15E, // Control chars? $-*
56	  };
57	  static final int ASTERISK_ENCODING = CHARACTER_ENCODINGS[47];
58	
59	  private final StringBuilder decodeRowResult;
60	  private final int[] counters;
61	
62	  public Code93Reader() {
63	    decodeRowResult = new StringBuilder(20);
64	    counters = new int[6];
65	  }
66	
67	  @Override
68	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
69	      throws NotFoundException, ChecksumException, FormatException {
70	
71	    int[] start = findAsteriskPattern(row);
72	    // Read off white space
73	    int nextStart = row.getNextSet(start[1]);
74	    int end = row.getSize();
75	
76	    int[] theCounters = counters;
77	    Arrays.fill(theCounters, 0);
78	    StringBuilder result = decodeRowResult;
79	    result.setLength(0);
80	
81	    char decodedChar;
82	    int lastStart;
83	    do {
84	      recordPattern(row, nextStart, theCounters);
85	      int pattern = toPattern(theCounters);
86	      if (pattern < 0) {
87	        throw NotFoundException.getNotFoundInstance();
88	      }
89	      decodedChar = patternToChar(pattern);
90	      result.append(decodedChar);
91	      lastStart = nextStart;
92	      for (int counter : theCounters) {
93	        nextStart += counter;
94	      }
95	      // Read off white space
96	      nextStart = row.getNextSet(nextStart);
97	    } while (decodedChar != '*');
98	    result.deleteCharAt(result.length() - 1); // remove asterisk
99	
100	    int lastPatternSize = MathUtils.sum(theCounters);
101	
102	    // Should be at least one more black module
103	    if (nextStart == end || !row.get(nextStart)) {
104	      throw NotFoundException.getNotFoundInstance();
105	    }
106	
107	    if (result.length() < 2) {
108	      // false positive -- need at least 2 checksum digits
109	      throw NotFoundException.getNotFoundInstance();
110	    }
111	
112	    checkChecksums(result);
113	    // Remove checksum digits
114	    result.setLength(result.length() - 2);
115	
116	    String resultString = decodeExtended(result);
117	
118	    float left = (start[1] + start[0]) / 2.0f;
119	    float right = lastStart + lastPatternSize / 2.0f;
120	
121	    Result resultObject = new Result(
122	        resultString,
123	        null,
124	        new ResultPoint[]{
125	            new ResultPoint(left, rowNumber),
126	            new ResultPoint(right, rowNumber)},
127	        BarcodeFormat.CODE_93);
128	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]G0");
129	    return resultObject;
130	  }
131	
132	  private int[] findAsteriskPattern(BitArray row) throws NotFoundException {
133	    int width = row.getSize();
134	    int rowOffset = row.getNextSet(0);
135	
136	    Arrays.fill(counters, 0);
137	    int[] theCounters = counters;
138	    int patternStart = rowOffset;
139	    boolean isWhite = false;
140	    int patternLength = theCounters.length;
141	
142	    int counterPosition = 0;
143	    for (int i = rowOffset; i < width; i++) {
144	      if (row.get(i) != isWhite) {
145	        theCounters[counterPosition]++;
146	      } else {
147	        if (counterPosition == patternLength - 1) {
148	          if (toPattern(theCounters) == ASTERISK_ENCODING) {
149	            return new int[]{patternStart, i};
150	          }
151	          patternStart += theCounters[0] + theCounters[1];
152	          System.arraycopy(theCounters, 2, theCounters, 0, counterPosition - 1);
153	          theCounters[counterPosition - 1] = 0;
154	          theCounters[counterPosition] = 0;
155	          counterPosition--;
156	        } else {
157	          counterPosition++;
158	        }
159	        theCounters[counterPosition] = 1;
160	        isWhite = !isWhite;
161	      }
162	    }
163	    throw NotFoundException.getNotFoundInstance();
164	  }
165	
166	  private static int toPattern(int[] counters) {
167	    int sum = MathUtils.sum(counters);
168	    int pattern = 0;
169	    int max = counters.length;
170	    for (int i = 0; i < max; i++) {
171	      int scaled = Math.round(counters[i] * 9.0f / sum);
172	      if (scaled < 1 || scaled > 4) {
173	        return -1;
174	      }
175	      if ((i & 0x01) == 0) {
176	        for (int j = 0; j < scaled; j++) {
177	          pattern = (pattern << 1) | 0x01;
178	        }
179	      } else {
180	        pattern <<= scaled;
181	      }
182	    }
183	    return pattern;
184	  }
185	
186	  private static char patternToChar(int pattern) throws NotFoundException {
187	    for (int i = 0; i < CHARACTER_ENCODINGS.length; i++) {
188	      if (CHARACTER_ENCODINGS[i] == pattern) {
189	        return ALPHABET[i];
190	      }
191	    }
192	    throw NotFoundException.getNotFoundInstance();
193	  }
194	
195	  private static String decodeExtended(CharSequence encoded) throws FormatException {
196	    int length = encoded.length();
197	    StringBuilder decoded = new StringBuilder(length);
198	    for (int i = 0; i < length; i++) {
199	      char c = encoded.charAt(i);
200	      if (c >= 'a' && c <= 'd') {
201	        if (i >= length - 1) {
202	          throw FormatException.getFormatInstance();
203	        }
204	        char next = encoded.charAt(i + 1);
205	        char decodedChar = '\0';
206	        switch (c) {
207	          case 'd':
208	            // +A to +Z map to a to z
209	            if (next >= 'A' && next <= 'Z') {
210	              decodedChar = (char) (next + 32);
211	            } else {
212	              throw FormatException.getFormatInstance();
213	            }
214	            break;
215	          case 'a':
216	            // $A to $Z map to control codes SH to SB
217	            if (next >= 'A' && next <= 'Z') {
218	              decodedChar = (char) (next - 64);
219	            } else {
220	              throw FormatException.getFormatInstance();
221	            }
222	            break;
223	          case 'b':
224	            if (next >= 'A' && next <= 'E') {
225	              // %A to %E map to control codes ESC to USep
226	              decodedChar = (char) (next - 38);
227	            } else if (next >= 'F' && next <= 'J') {
228	              // %F to %J map to ; < = > ?
229	              decodedChar = (char) (next - 11);
230	            } else if (next >= 'K' && next <= 'O') {
231	              // %K to %O map to [ \ ] ^ _
232	              decodedChar = (char) (next + 16);
233	            } else if (next >= 'P' && next <= 'T') {
234	              // %P to %T map to { | } ~ DEL
235	              decodedChar = (char) (next + 43);
236	            } else if (next == 'U') {
237	              // %U map to NUL
238	              decodedChar = '\0';
239	            } else if (next == 'V') {
240	              // %V map to @
241	              decodedChar = '@';
242	            } else if (next == 'W') {
243	              // %W map to `
244	              decodedChar = '`';
245	            } else if (next >= 'X' && next <= 'Z') {
246	              // %X to %Z all map to DEL (127)
247	              decodedChar = 127;
248	            } else {
249	              throw FormatException.getFormatInstance();
250	            }
251	            break;
252	          case 'c':
253	            // /A to /O map to ! to , and /Z maps to :
254	            if (next >= 'A' && next <= 'O') {
255	              decodedChar = (char) (next - 32);
256	            } else if (next == 'Z') {
257	              decodedChar = ':';
258	            } else {
259	              throw FormatException.getFormatInstance();
260	            }
261	            break;
262	        }
263	        decoded.append(decodedChar);
264	        // bump up i again since we read two characters
265	        i++;
266	      } else {
267	        decoded.append(c);
268	      }
269	    }
270	    return decoded.toString();
271	  }
272	
273	  private static void checkChecksums(CharSequence result) throws ChecksumException {
274	    int length = result.length();
275	    checkOneChecksum(result, length - 2, 20);
276	    checkOneChecksum(result, length - 1, 15);
277	  }
278	
279	  private static void checkOneChecksum(CharSequence result, int checkPosition, int weightMax)
280	      throws ChecksumException {
281	    int weight = 1;
282	    int total = 0;
283	    for (int i = checkPosition - 1; i >= 0; i--) {
284	      total += weight * ALPHABET_STRING.indexOf(result.charAt(i));
285	      if (++weight > weightMax) {
286	        weight = 1;
287	      }
288	    }
289	    if (result.charAt(checkPosition) != ALPHABET[total % 47]) {
290	      throw ChecksumException.getChecksumInstance();
291	    }
292	  }
293	
294	}
