234	      throw new IllegalArgumentException("Num bits must be between 0 and 32");
235	    }
236	    int nextSize = size;
237	    ensureCapacity(nextSize + numBits);
238	    for (int numBitsLeft = numBits - 1; numBitsLeft >= 0; numBitsLeft--) {
239	      if ((value & (1 << numBitsLeft)) != 0) {
