247	  public void appendBitArray(BitArray other) {
248	    int otherSize = other.size;
249	    ensureCapacity(size + otherSize);
250	    for (int i = 0; i < otherSize; i++) {
251	      appendBit(other.get(i));
252	    }
253	  }
