255	  public void xor(BitArray other) {
256	    if (size != other.size) {
257	      throw new IllegalArgumentException("Sizes don't match");
258	    }
259	    for (int i = 0; i < bits.length; i++) {
260	      // The last int could be incomplete (i.e. not have 32 bits in
261	      // it) but there is no problem since 0 XOR 0 == 0.
262	      bits[i] ^= other.bits[i];
263	    }
