271	   * @param offset position in array to start writing
272	   * @param numBytes how many bytes to write
273	   */
274	  public void toBytes(int bitOffset, byte[] array, int offset, int numBytes) {
275	    for (int i = 0; i < numBytes; i++) {
276	      int theByte = 0;
277	      for (int j = 0; j < 8; j++) {
278	        if (get(bitOffset)) {
279	          theByte |= 1 << (7 - j);
280	        }
281	        bitOffset++;
282	      }
283	      array[offset + i] = (byte) theByte;
