295	  /**
296	   * Reverses all bits in the array.
297	   */
298	  public void reverse() {
299	    int[] newBits = new int[bits.length];
300	    // reverse all int's first
301	    int len = (size - 1) / 32;
302	    int oldBitsLen = len + 1;
303	    for (int i = 0; i < oldBitsLen; i++) {
304	      newBits[len - i] = Integer.reverse(bits[i]);
305	    }
306	    // now correct the int's if the bit size isn't a multiple of 32
307	    if (size != oldBitsLen * 32) {
