309	      int currentInt = newBits[0] >>> leftOffset;
310	      for (int i = 1; i < oldBitsLen; i++) {
311	        int nextInt = newBits[i];
312	        currentInt |= nextInt << (32 - leftOffset);
313	        newBits[i - 1] = currentInt;
314	        currentInt = nextInt >>> leftOffset;
315	      }
316	      newBits[oldBitsLen - 1] = currentInt;
317	    }
